func metaChildrenRuntimeDependencies(s map[string]bool) []*som.SomMetaNode {
	return []*som.SomMetaNode{
		{ClassName: "RuntimeDependencies", MemberName: "content", Kind: som.SomMetaKindContent, TypeName: "String", SerializationOrder: metaIntPtr(0), ContentType: &som.SomContentTypeMeta{Type: "text", Description: ""}, ContentHelp: "## Runtime Dependencies (12.4)\n\nRuntime dependencies between components.\n\n### Dependency Properties\n- **Startup order** — Boot sequence priority\n- **Health checks** — Verification method and interval\n- **Failover behavior** — Graceful degradation, circuit breaker\n- **Version constraints** — Required versions or ranges\n- **Criticality** — Impact if unavailable\n\n### Dependency Types\n- **Critical** — System cannot function without\n- **Optional** — Enhances functionality but not required\n- **Conditional** — Required only in specific configurations\n\n### Documentation\nFor each dependency, document latency tolerance, caching\nstrategy, and fallback alternatives.\n"},
		func() *som.SomMetaNode {
			n := &som.SomMetaNode{ClassName: "RuntimeDependencies", MemberName: "items", SectionID: "RNDEP-ITEM-LST", SectionIDPattern: "RNDEP-ITEM-xxx", Kind: som.SomMetaKindList, TypeName: "RuntimeDependencyEntry", SerializationOrder: metaIntPtr(1), ContentHelp: "Add one entry per runtime dependency.", DocComment: "Contains 0+× Runtime Dependency.", Extra: []*som.SomMetaExtra{{Annotation: "StandardReferences", Args: map[string]interface{}{"standards": []interface{}{"ISO/IEC 25010:2023 — the product quality model defines reliability sub-characteristics such as availability, fault tolerance, and recoverability"}, "connotation": "Holds the list of runtime dependency entries governing startup order, health checks, and failover."}}}}
			n.ElementNode = metaCx("RuntimeDependencyEntry", s, metaChildrenRuntimeDependencyEntry, func(r bool, c []*som.SomMetaNode) *som.SomMetaNode {
				return &som.SomMetaNode{ClassName: "RuntimeDependencyEntry", ClassSectionID: "RNDEP", Kind: som.SomMetaKindComplex, TypeName: "RuntimeDependencyEntry", DocComment: "A runtime dependency entry (form).\n\nDocuments one runtime dependency: startup order, health checks,\nfailover, data flow, latency tolerance, and caching strategy.", ClassDocComment: "A runtime dependency entry (form).\n\nDocuments one runtime dependency: startup order, health checks,\nfailover, data flow, latency tolerance, and caching strategy.", Recursive: r, Children: c}
			})
			return n
		}(),
	}
}

