func metaChildrenSensitiveDataEncryption(s map[string]bool) []*som.SomMetaNode {
	return []*som.SomMetaNode{
		{ClassName: "SensitiveDataEncryption", MemberName: "content", Kind: som.SomMetaKindContent, TypeName: "String", SerializationOrder: metaIntPtr(0), ContentType: &som.SomContentTypeMeta{Type: "text", Description: ""}, ContentHelp: "Define encryption requirements for sensitive data both at rest and in transit.\nEncryption is a critical defense-in-depth layer that protects data even when\nother controls fail.\n\n**Data classification:**\n- Identify sensitive data categories (PII, PHI, financial, credentials)\n- Map each category to encryption requirements\n- Document regulatory drivers (GDPR, HIPAA, PCI DSS)\n\n**Encryption scope:**\n- **At Rest**: Stored data in databases, filesystems, backups\n- **In Transit**: Data moving over networks (internal and external)\n- **In Use**: Data in memory (future consideration for confidential computing)\n\n**Key management:**\n- Cryptographic key lifecycle (generation, storage, rotation, destruction)\n- Key hierarchy (master keys, data encryption keys)\n- Separation of duties (key custodians vs. data operators)\n\n**Algorithm selection:**\n- Use approved algorithms (AES-256-GCM, ChaCha20-Poly1305)\n- Avoid deprecated algorithms (DES, 3DES, RC4, MD5, SHA-1)\n- Plan for post-quantum cryptography migration\n\n**Compliance alignment:**\n- PCI DSS: encrypt cardholder data at rest and in transit\n- HIPAA: protect PHI with appropriate safeguards\n- GDPR: implement appropriate technical measures\n\n**Reference:**\n- OWASP Cryptographic Storage Cheat Sheet\n- NIST SP 800-175B: Cryptographic Standards and Guidelines\n"},
		metaCx("EncryptionAtRest", s, metaChildrenEncryptionAtRest, func(r bool, c []*som.SomMetaNode) *som.SomMetaNode {
			return &som.SomMetaNode{ClassName: "EncryptionAtRest", MemberName: "encryptionAtRest", ClassSectionID: "ENATRE", Kind: som.SomMetaKindComplex, TypeName: "EncryptionAtRest", SerializationOrder: metaIntPtr(1), DocComment: "9.5.1. Encryption At Rest.", ClassDocComment: "9.5.1. Encryption At Rest.\n\nDefines encryption requirements for stored data: algorithms, key lengths,\nencryption layers (application, database, filesystem, hardware), field-level\nand full-disk encryption, encrypted data categories, backup encryption,\nand compliance requirements. Aligns with OWASP Cryptographic Storage\nCheat Sheet and NIST SP 800-111 (Storage Encryption).", Recursive: r, Children: c}
		}),
		metaCx("EncryptionInTransit", s, metaChildrenEncryptionInTransit, func(r bool, c []*som.SomMetaNode) *som.SomMetaNode {
			return &som.SomMetaNode{ClassName: "EncryptionInTransit", MemberName: "encryptionInTransit", ClassSectionID: "ENINTR", Kind: som.SomMetaKindComplex, TypeName: "EncryptionInTransit", SerializationOrder: metaIntPtr(2), DocComment: "9.5.2. Encryption In Transit.", ClassDocComment: "9.5.2. Encryption In Transit.\n\nDefines encryption requirements for data in transit: TLS protocol versions,\ncipher suites, certificate management, HSTS policy, mutual TLS, certificate\npinning, and internal/service-to-service communication encryption. Aligns\nwith OWASP Transport Layer Security Cheat Sheet and NIST SP 800-52.", Recursive: r, Children: c}
		}),
		metaCx("KeyManagement", s, metaChildrenKeyManagement, func(r bool, c []*som.SomMetaNode) *som.SomMetaNode {
			return &som.SomMetaNode{ClassName: "KeyManagement", MemberName: "keyManagement", ClassSectionID: "KEMA", Kind: som.SomMetaKindComplex, TypeName: "KeyManagement", SerializationOrder: metaIntPtr(3), DocComment: "9.5.3. Key Management.", ClassDocComment: "9.5.3. Key Management.\n\nDefines cryptographic key management policies covering the full key\nlifecycle: generation, storage, rotation, escrow/backup, and compromise\nrecovery. Aligns with OWASP Key Management Cheat Sheet and\nNIST SP 800-57 (Recommendation for Key Management).", Recursive: r, Children: c}
		}),
	}
}

